const prisma = new PrismaClient();

const buildWhyInterviewersAsk = (question: string, shortDescription: string) =>
  `Interviewers ask this to assess whether you can explain QA concepts clearly and connect them to practical testing decisions, risks, evidence, and trade-offs.`;

async function main() {
  const category = await prisma.category.upsert({
    where: { slug: "quality-assurance" },
    update: { name: "Quality Assurance", group: "Technology", description: "Quality Assurance and software testing interview questions." },
    create: { name: "Quality Assurance", slug: "quality-assurance", group: "Technology", description: "Quality Assurance and software testing interview questions." },
  });

  const subcategory = await prisma.subcategory.upsert({
    where: { categoryId_slug: { categoryId: category.id, slug: "quality-assurance" } },
    update: {},
    create: { name: "Quality Assurance", slug: "quality-assurance", categoryId: category.id },
  });

  for (let topicIndex = 0; topicIndex < topics.length; topicIndex += 1) {
    const [, question, slug, shortDescription, sampleAnswer] = topics[topicIndex];
    const experienceLevel = topicIndex < 70 ? ExperienceLevel.FRESHER : topicIndex < 145 ? ExperienceLevel.MID_LEVEL : ExperienceLevel.EXPERIENCED;
    const difficulty = topicIndex < 70 ? Difficulty.EASY : topicIndex < 145 ? Difficulty.MEDIUM : Difficulty.HARD;
    const interviewType = InterviewType.TECHNICAL;
    const commonMistakes = [
      "Giving only a memorized definition",
      "Ignoring negative cases, boundaries, or failure conditions",
      "Choosing a tool without explaining the testing objective",
      "Treating test counts or pass percentages as proof of quality",
    ];
    const followUpQuestions = [
      topics[(topicIndex + 1) % topics.length][1],
      topics[(topicIndex + 2) % topics.length][1],
      topics[(topicIndex + 3) % topics.length][1],
    ];

    await prisma.interviewQuestion.upsert({
      where: { slug },
      update: {
        question, categoryId: category.id, subcategoryId: subcategory.id, experienceLevel, difficulty, interviewType,
        shortDescription, explanation: buildWhyInterviewersAsk(question, shortDescription), sampleAnswer, detailedAnswer: sampleAnswer,
        keyPoints: [], commonMistakes, followUpQuestions, tags: ["QA", "Quality Assurance", "Software Testing"], isPublished: true,
      },
      create: {
        question, slug, categoryId: category.id, subcategoryId: subcategory.id, experienceLevel, difficulty, interviewType,
        shortDescription, explanation: buildWhyInterviewersAsk(question, shortDescription), sampleAnswer, detailedAnswer: sampleAnswer,
        keyPoints: [], commonMistakes, followUpQuestions, tags: ["QA", "Quality Assurance", "Software Testing"], isPublished: true,
      },
    });
  }

  console.log(`Imported ${topics.length} Quality Assurance questions.`);
}

main().catch((error) => {
  console.error("ERROR: QA seed failed:", error);
  process.exit(1);
}).finally(() => prisma.$disconnect());